CREATE EXTENSION IF NOT EXISTS "pgcrypto";
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, email text NOT NULL UNIQUE, phone text, password_hash text NOT NULL, role text NOT NULL, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE customers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_code text NOT NULL UNIQUE, name text NOT NULL, phone text NOT NULL, whatsapp_number text, address text, village text, district text, gst_number text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX customers_phone_idx ON customers(phone);
CREATE TABLE drying_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), job_number text NOT NULL UNIQUE, customer_id uuid NOT NULL REFERENCES customers(id), product_type text NOT NULL, status text NOT NULL, received_at timestamptz NOT NULL, expected_completion_at timestamptz, completed_at timestamptz, notes text, created_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX drying_jobs_status_idx ON drying_jobs(status);
CREATE TABLE weight_measurements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), drying_job_id uuid NOT NULL REFERENCES drying_jobs(id) ON DELETE CASCADE, measurement_type text NOT NULL, weight_kg numeric(12,3) NOT NULL CHECK(weight_kg>0), moisture_percentage numeric(5,2) CHECK(moisture_percentage BETWEEN 0 AND 100), measured_at timestamptz NOT NULL, measured_by uuid REFERENCES users(id), notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE job_status_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), drying_job_id uuid NOT NULL REFERENCES drying_jobs(id) ON DELETE CASCADE, old_status text, new_status text NOT NULL, changed_by uuid REFERENCES users(id), reason text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE charges (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), drying_job_id uuid NOT NULL REFERENCES drying_jobs(id) ON DELETE CASCADE, charge_type text NOT NULL, description text NOT NULL, quantity numeric(12,3) NOT NULL, unit text NOT NULL, rate numeric(12,2) NOT NULL, amount numeric(12,2) NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE invoices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_number text NOT NULL UNIQUE, drying_job_id uuid NOT NULL UNIQUE REFERENCES drying_jobs(id), customer_id uuid NOT NULL REFERENCES customers(id), subtotal numeric(12,2) NOT NULL, discount numeric(12,2) NOT NULL DEFAULT 0, tax_amount numeric(12,2) NOT NULL DEFAULT 0, total_amount numeric(12,2) NOT NULL, status text NOT NULL, issued_at timestamptz NOT NULL, due_at timestamptz, pdf_url text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE invoice_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_id uuid NOT NULL REFERENCES invoices(id) ON DELETE CASCADE, description text NOT NULL, quantity numeric(12,3) NOT NULL, unit text NOT NULL, rate numeric(12,2) NOT NULL, amount numeric(12,2) NOT NULL);
CREATE TABLE payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_id uuid NOT NULL REFERENCES invoices(id), amount numeric(12,2) NOT NULL CHECK(amount>0), payment_method text NOT NULL, transaction_reference text UNIQUE, paid_at timestamptz NOT NULL, received_by uuid REFERENCES users(id), notes text, created_at timestamptz NOT NULL DEFAULT now());
